// generar_286_analisis_contenedores_y_reorden.js
// CHIQUI Entre Señales — Análisis: dos secciones en contenedores con
// fondo (como el mockup), reorden y renombres
//
// 1) SECCIÓN "ESTADO DE SALUD" (contenedor con fondo crema #F0E2CE)
//    Envuelve visualmente en un solo cuadro los bloques que hablan de
//    cómo ha estado la mascota:
//      · Lo observado este mes  → ahora DESPLEGABLE, cerrado por defecto
//      · Signos de alerta (si los hay)
//      · Normalidad por categoría
//      · Últimos 7 días
//
// 2) SECCIÓN "ACTIVIDAD FÍSICA" (antes "Paseo"; fondo canela suave
//    #FBEEDD) — contenedor con fondo, con este orden que cuenta mejor
//    la historia:
//      Visibles siempre: 🔥 Racha de paseos · 🕒 Paseo en [mes]
//      Luego, en orden:
//        📊 Historial mensual de paseos   (antes "Tiempo de paseo por mes")
//        📋 Estadísticas del mes          (antes "Detalle de [mes]")
//        🧩 Enriquecimiento y entrenamiento
//        📅 Resumen de actividad semanal  (antes "Actividad de la semana")
//
//    Cambios de nombre incluidos. El "Resumen de actividad semanal"
//    pasó al final (antes iba entre Historial y Estadísticas).
//
// El título "Paseo en [mes]" sigue siendo dinámico: el 1 de agosto
// dirá "Paseo en agosto" solo y el contador partirá de cero.
//
// No hay SQL. Solo reescribe app/analisis/page.tsx.
//
// Uso:
//   node generar_286_analisis_contenedores_y_reorden.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
